const $=s=>document.querySelector(s);
const regions={capital:{name:'ソウル・京畿',culture:'歴史・文化施設をめぐる',food:'地域の食文化を体験',city:'都市建築・街歩き'},coast:{name:'釜山・蔚山',culture:'港町の文化を知る',food:'海辺のローカルグルメ体験',city:'海辺の都市景観をめぐる'},science:{name:'大田',culture:'地域の歴史・文化に触れる',food:'地元の食文化を体験',city:'研究都市の街歩き'}};
const fields={digital:{name:'AI・デジタル技術',region:'capital',visit:'AI・デジタル技術に関する企業交流'},chips:{name:'半導体・電子部品',region:'capital',visit:'半導体・電子部品分野の技術交流'},manufacturing:{name:'製造・モビリティ・物流',region:'coast',visit:'製造・モビリティ・物流分野の視察'},bio:{name:'バイオ・ヘルスケア',region:'science',visit:'バイオ・ヘルスケア分野の研究交流'}};
let currentPlan=null;
const localDate=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const today=localDate(new Date());$('#start').min=today;$('#end').min=today;
const later=new Date();later.setDate(later.getDate()+14);$('#start').value=localDate(later);later.setDate(later.getDate()+2);$('#end').value=localDate(later);
$('#start').addEventListener('change',()=>{$('#end').min=$('#start').value||today;if($('#end').value<$('#start').value)$('#end').value=$('#start').value;});
function el(tag,txt,cls){const x=document.createElement(tag);if(txt)x.textContent=txt;if(cls)x.className=cls;return x;}
function makePlan(data){const field=fields[data.field],key=data.region==='auto'?field.region:data.region,region=regions[key];const days=Math.round((Date.parse(data.end)-Date.parse(data.start))/86400000)+1;if(!Number.isInteger(days)||days<1||days>7||data.start<today)throw Error('開始日以降の1〜7日間を選択してください。');const entries=[];for(let i=0;i<days;i++){const d=new Date(data.start+'T12:00:00');d.setDate(d.getDate()+i);const tour=data.tours.length?region[data.tours[i%data.tours.length]]:'自由時間・追加打合せ';entries.push({date:localDate(d),items:[['09:30',i===0?'視察目的の共有・オリエンテーション':'前日の振り返り・現地への移動'],['10:30',field.visit+'（受入先調整が必要）'],['12:30','昼食・移動のための余裕時間'],['14:30',tour+'（施設・経路は調整予定）'],['17:00','振り返り・意見交換']]});}return{...data,regionName:region.name,fieldName:field.name,days:entries};}
$('#plan-form').addEventListener('submit',e=>{e.preventDefault();$('#error').textContent='';try{currentPlan=makePlan({field:$('#field').value,region:$('#region').value,start:$('#start').value,end:$('#end').value,people:$('#people').value,theme:$('#theme').value.trim(),tours:[...document.querySelectorAll('input[name=tour]:checked')].map(x=>x.value)});renderPlan();}catch(err){$('#error').textContent=err.message;}});
function renderPlan(){const target=$('#result');target.replaceChildren();const top=el('div',null,'formtop');top.append(el('h3','あなたへのおすすめプラン'),el('span','02 — PLAN'));target.append(top,el('p',currentPlan.regionName+' / '+currentPlan.days.length+'日間 / '+currentPlan.people+'名','result-intro'),el('p',currentPlan.fieldName+'に合わせた地域と体験の組み合わせです。','result-intro'));if(currentPlan.theme)target.append(el('p','相談時に共有する研究テーマ：'+currentPlan.theme,'fine'));target.append(el('p','提案デモ：研究テーマの自由記述はAI解析していません。時刻は目安で、営業日・移動時間・空き状況は未確認です。','fine'));currentPlan.days.forEach((day,i)=>{const block=el('article',null,'day');block.append(el('h4','DAY '+(i+1)+' · '+day.date));day.items.forEach(([time,txt])=>{const p=el('p');p.append(el('time',time),document.createTextNode(txt));block.append(p);});target.append(block);});const actions=el('div',null,'result-actions');const back=el('button','条件を変更','textbutton');back.type='button';back.onclick=()=>{target.hidden=true;$('#plan-form').hidden=false;$('#field').focus();};const apply=el('button','申込内容を確認 ↗','button');apply.onclick=()=>{$('#application-summary').textContent=summary();$('#apply-dialog').showModal();};actions.append(back,apply);target.append(actions);$('#plan-form').hidden=true;target.hidden=false;target.scrollIntoView({behavior:'smooth',block:'start'});}
function summary(){return `【相談用・未送信】\n地域：${currentPlan.regionName}\n研究分野：${currentPlan.fieldName}\n日程：${currentPlan.start} ～ ${currentPlan.end}\n参加人数：${currentPlan.people}名\n研究テーマ：${currentPlan.theme||'未記入'}\nステータス：デモ・旅行会社への接続前`}
$('#close-dialog').onclick=()=>$('#apply-dialog').close();$('#apply-dialog').addEventListener('click',e=>{if(e.target===$('#apply-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
$('#download').onclick=()=>{const content=summary()+'\n\n'+currentPlan.days.map((d,i)=>'DAY '+(i+1)+' '+d.date+'\n'+d.items.map(x=>x.join(' ')).join('\n')).join('\n\n')+'\n\nこれはルールベースの提案デモです。施設の受入可否・営業日・交通・通訳・費用は旅行会社との確認が必要です。実際の申し込みは送信されていません。';const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'}));const a=el('a');a.href=url;a.download='kij-journey-draft.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
document.querySelectorAll('[data-region]').forEach(btn=>btn.onclick=()=>{$('#region').value=btn.dataset.region;$('#result').hidden=true;$('#plan-form').hidden=false;$('#planner').scrollIntoView({behavior:'smooth'});});
